def align_scores(grid, band1, band2, bg, maxshift=3):
    n=band1[1]-band1[0]
    scores={s:0 for s in range(-maxshift,maxshift+1)}
    counts={s:0 for s in scores}
    for off in range(n):
        a=grid[band1[0]+off]; b=grid[band2[0]+off]
        enda=max(c for c,v in enumerate(a) if v!=bg); endb=max(c for c,v in enumerate(b) if v!=bg)
