            for c in range(lo,hi+1):
                scores[s]+= (a[c]!=bg)!=(b[c+s]!=bg)
                counts[s]+=1
    return sorted((scores[s]/counts[s] if counts[s] else 99,s,scores[s],counts[s]) for s in scores)
